import bisect

class MedianFinder:
    def __init__(self) -> None:
        self.data: list[int] = []

    def addNum(self, num: int) -> None:
        bisect.insort(self.data, num)  # O(n) shift

    def findMedian(self) -> float:
        n = len(self.data)
        if n % 2 == 1:
            return float(self.data[n // 2])
        return (self.data[n // 2 - 1] + self.data[n // 2]) / 2.0

