class MedianFinder {
    // low: max-heap of the smaller half. high: min-heap of the larger half.
    private PriorityQueue<Integer> low =
        new PriorityQueue<>(Collections.reverseOrder());
    private PriorityQueue<Integer> high = new PriorityQueue<>();

    public void addNum(int num) {
        low.offer(num);            // 1) always add to low
        high.offer(low.poll());    // 2) move low's max into high (order invariant)
        if (high.size() > low.size()) {
            low.offer(high.poll()); // 3) rebalance so low ≥ high in size
        }
    }

    public double findMedian() {
        if (low.size() > high.size()) {
            return low.peek();
        }
        return (low.peek() + high.peek()) / 2.0;
    }
}

