import heapq

class MedianFinder:
    def __init__(self) -> None:
        self.low: list[int] = []   # max-heap via negation (smaller half)
        self.high: list[int] = []  # min-heap (larger half)

    def addNum(self, num: int) -> None:
        heapq.heappush(self.low, -num)          # 1) add to low (negated)
        heapq.heappush(self.high, -heapq.heappop(self.low))  # 2) move max across
        if len(self.high) > len(self.low):       # 3) rebalance
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def findMedian(self) -> float:
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2.0

